use vstd::prelude::*;

verus! {

fn meshgrid(x: Vec<f32>, y: Vec<f32>) -> (Vec<Vec<f32>>, Vec<Vec<f32>>)
    ensures
        // The output matrices have dimensions (rows = y.len()) x (cols = x.len())
        |res: (Vec<Vec<f32>>, Vec<Vec<f32>>)| {
            let (x_mat, y_mat) = &res;
            x_mat.len() == y.len() &&
            y_mat.len() == y.len() &&
            forall(|row: usize| row < y.len() ==> x_mat[row].len() == x.len() && y_mat[row].len() == x.len()) &&
            // Each row of x_mat equals x
            forall(|row: usize| row < y.len() ==> x_mat[row] == x) &&
            // Each row of y_mat is filled with y[row]
            forall(|row: usize| row < y.len() ==>
                forall(|col: usize| col < x.len() ==> y_mat[row][col] == y[row])
            )
        },
{
    let rows = y.len();
    let cols = x.len();

    // Construct first matrix: each row is a clone of x
    let x_matrix = vec![x.clone(); rows];

    // Construct second matrix: each row is y[i] repeated cols times
    let y_matrix = y
        .iter()
        .map(|&val| vec![val; cols])
        .collect::<Vec<_>>();

    (x_matrix, y_matrix)
}

}